"use client";

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
// eslint-disable-next-line @typescript-eslint/no-unused-vars
import { Cloud, Link2, CheckCircle2, ArrowRight } from "lucide-react";
import { fetchApi } from "@/lib/api";

export default function CRMSettingsPage() {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [settings, setSettings] = useState<any>(null);
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const [loading, setLoading] = useState(true);
  const [syncing, setSyncing] = useState(false);
  const [showHubspotForm, setShowHubspotForm] = useState(false);
  const [apiKey, setApiKey] = useState("");

  useEffect(() => {
    fetchSettings();
  }, []);

  const fetchSettings = async () => {
    try {
      const res = await fetchApi('/crm/settings');
      setSettings(res?.data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleConnect = async (provider: string) => {
    try {
      await fetchApi('/crm/settings', {
        method: "POST",
        body: JSON.stringify({ provider, credentials: { apiKey }, field_mappings: {} })
      });
      setShowHubspotForm(false);
      fetchSettings();
    } catch (err) {
      console.error(err);
    }
  };

  const handleSync = async () => {
    setSyncing(true);
    try {
      await fetchApi('/crm/sync', { method: "POST" });
      fetchSettings();
    } catch (err) {
      console.error(err);
    } finally {
      setSyncing(false);
    }
  };

  return (
    <div className="space-y-8 max-w-4xl">
      <div>
        <h1 className="text-3xl font-bold tracking-tight text-white flex items-center gap-2">
          <Link2 className="w-8 h-8 text-indigo-400" />
          Connect CRM
        </h1>
        <p className="text-muted-foreground mt-1">Sync your leads and customer data directly with your CRM.</p>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        {/* HubSpot Card */}
        <Card className="bg-[#1E1E2E] border-[#3F3F5A] text-white">
          <CardHeader className="flex flex-row items-center gap-4">
            <div className="w-12 h-12 rounded-xl bg-orange-500/10 flex items-center justify-center border border-orange-500/20 text-orange-500 font-bold text-2xl">
              H
            </div>
            <div className="flex-1">
              <CardTitle className="text-xl">HubSpot</CardTitle>
              {settings?.provider === 'hubspot' && settings?.status === 'active' ? (
                <Badge className="bg-emerald-500/10 text-emerald-400 border-emerald-500/20 mt-1">Connected</Badge>
              ) : (
                <Badge variant="outline" className="border-gray-500/30 text-gray-400 mt-1">Not Connected</Badge>
              )}
            </div>
          </CardHeader>
          <CardContent>
            {settings?.provider === 'hubspot' && settings?.status === 'active' ? (
              <div className="space-y-4">
                <p className="text-sm text-gray-400">Last sync: {settings?.last_sync_at ? new Date(settings.last_sync_at).toLocaleString() : 'Never'}</p>
                <div className="flex gap-3">
                  <Button onClick={handleSync} disabled={syncing} className="bg-indigo-600 hover:bg-indigo-700">
                    {syncing ? 'Syncing...' : 'Sync Now'}
                  </Button>
                </div>
              </div>
            ) : (
              <div className="space-y-4">
                {showHubspotForm ? (
                  <div className="space-y-3">
                    <Input 
                      placeholder="HubSpot API Key" 
                      value={apiKey}
                      onChange={(e) => setApiKey(e.target.value)}
                      className="bg-[#2A2A3C] border-[#3F3F5A] text-white" 
                    />
                    <div className="flex gap-2">
                      <Button onClick={() => handleConnect('hubspot')} className="bg-orange-500 hover:bg-orange-600 flex-1">Connect</Button>
                      <Button variant="outline" onClick={() => setShowHubspotForm(false)} className="border-[#3F3F5A] text-gray-300 hover:text-white">Cancel</Button>
                    </div>
                  </div>
                ) : (
                  <Button onClick={() => setShowHubspotForm(true)} className="w-full bg-orange-500 hover:bg-orange-600">Connect HubSpot</Button>
                )}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Salesforce Card */}
        <Card className="bg-[#1E1E2E] border-[#3F3F5A] text-white">
          <CardHeader className="flex flex-row items-center gap-4">
            <div className="w-12 h-12 rounded-xl bg-blue-500/10 flex items-center justify-center border border-blue-500/20">
              <Cloud className="w-6 h-6 text-blue-500" />
            </div>
            <div className="flex-1">
              <CardTitle className="text-xl">Salesforce</CardTitle>
              {settings?.provider === 'salesforce' && settings?.status === 'active' ? (
                <Badge className="bg-emerald-500/10 text-emerald-400 border-emerald-500/20 mt-1">Connected</Badge>
              ) : (
                <Badge variant="outline" className="border-gray-500/30 text-gray-400 mt-1">Not Connected</Badge>
              )}
            </div>
          </CardHeader>
          <CardContent>
            {settings?.provider === 'salesforce' && settings?.status === 'active' ? (
              <div className="space-y-4">
                <p className="text-sm text-gray-400">Last sync: {settings?.last_sync_at ? new Date(settings.last_sync_at).toLocaleString() : 'Never'}</p>
                <div className="flex gap-3">
                  <Button onClick={handleSync} disabled={syncing} className="bg-blue-600 hover:bg-blue-700">
                    {syncing ? 'Syncing...' : 'Sync Now'}
                  </Button>
                </div>
              </div>
            ) : (
              <Button variant="outline" className="w-full border-[#3F3F5A] text-gray-300 hover:text-white" onClick={() => alert("Salesforce coming soon!")}>
                Connect Salesforce
              </Button>
            )}
          </CardContent>
        </Card>
      </div>

      <Card className="bg-[#1E1E2E] border-[#3F3F5A] text-white">
        <CardHeader>
          <CardTitle>Field Mapping</CardTitle>
          <CardDescription className="text-gray-400">How your AI data maps to CRM fields</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            <div className="flex items-center gap-4 p-3 bg-[#2A2A3C] rounded-lg border border-[#3F3F5A]">
              <div className="flex-1 font-medium text-gray-300">Lead Name</div>
              <ArrowRight className="w-4 h-4 text-gray-500" />
              <div className="flex-1 font-medium text-indigo-300 text-right">Contact Name</div>
            </div>
            <div className="flex items-center gap-4 p-3 bg-[#2A2A3C] rounded-lg border border-[#3F3F5A]">
              <div className="flex-1 font-medium text-gray-300">Email</div>
              <ArrowRight className="w-4 h-4 text-gray-500" />
              <div className="flex-1 font-medium text-indigo-300 text-right">Email</div>
            </div>
            <div className="flex items-center gap-4 p-3 bg-[#2A2A3C] rounded-lg border border-[#3F3F5A]">
              <div className="flex-1 font-medium text-gray-300">Company</div>
              <ArrowRight className="w-4 h-4 text-gray-500" />
              <div className="flex-1 font-medium text-indigo-300 text-right">Account</div>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import { Building } from "lucide-react";
import { useUserContext } from "@/contexts/UserContext";

const T = {
  g:       "#00ff88",
  bg:      "#040810",
  bg2:     "#070e1a",
  panel:   "#0a1628",
  border:  "rgba(0,255,136,0.18)",
  muted:   "rgba(0,255,136,0.45)",
  text:    "#c8ffe8",
  glow:    "0 0 20px rgba(0,255,136,0.35),0 0 60px rgba(0,255,136,0.12)",
  mono:    "'Share Tech Mono', monospace",
  display: "'Orbitron', sans-serif",
  body:    "'Rajdhani', sans-serif",
};

const Corners = () => (
  <>
    {[["tl","1px 0 0 1px","0","0","auto","auto"],
      ["tr","1px 1px 0 0","0","auto","0","auto"],
      ["bl","0 0 1px 1px","auto","0","auto","0"],
      ["br","0 1px 1px 0","auto","auto","0","0"]].map(([k, bw, t, l, b, r]) => (
      <span key={k} style={{
        position:"absolute", width:14, height:14,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        borderColor: T.g, borderStyle:"solid", borderWidth: bw as any, opacity: 0.5,
        top:t==="auto"?undefined:8, left:l==="auto"?undefined:8,
        bottom:b==="auto"?undefined:8, right:r==="auto"?undefined:8,
      }}/>
    ))}
  </>
);

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const SettingSection = ({ title, icon: Icon, children }: any) => (
  <div style={{ background: T.panel, border: `1px solid ${T.border}`, padding: "2rem", position: "relative", marginBottom: "2rem" }}>
    <Corners />
    <div style={{ display: "flex", alignItems: "center", gap: "0.8rem", marginBottom: "1.5rem" }}>
      <Icon size={18} color={T.g} />
      <div style={{ fontFamily: T.display, fontSize: "1.2rem", fontWeight: 700, color: "#fff" }}>{title}</div>
    </div>
    {children}
  </div>
);

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const Input = ({ label, value, type = "text", onChange }: any) => (
  <div style={{ marginBottom: "1rem" }}>
    <label style={{ fontFamily:T.mono, fontSize:"0.65rem", letterSpacing:"0.12em", color:T.muted, marginBottom:"0.4rem", display:"block", textTransform:"uppercase" }}>{label}</label>
    <input type={type} value={value} onChange={onChange} style={{
      width: "100%", background: "rgba(0,255,136,0.03)", border: `1px solid ${T.border}`,
      color: T.text, fontFamily: T.mono, fontSize: "0.85rem", padding: "0.8rem", outline: "none"
    }} />
  </div>
);

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const Select = ({ label, value, onChange, options }: any) => (
  <div style={{ marginBottom: "1rem" }}>
    <label style={{ fontFamily:T.mono, fontSize:"0.65rem", letterSpacing:"0.12em", color:T.muted, marginBottom:"0.4rem", display:"block", textTransform:"uppercase" }}>{label}</label>
    <select value={value} onChange={onChange} style={{
      width: "100%", background: "rgba(0,255,136,0.03)", border: `1px solid ${T.border}`,
      color: T.text, fontFamily: T.mono, fontSize: "0.85rem", padding: "0.8rem", outline: "none", appearance: "none"
    }}>
      {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
      {options.map((opt: any) => (
        <option key={opt.value} value={opt.value} style={{ background: T.panel, color: T.text }}>
          {opt.label}
        </option>
      ))}
    </select>
  </div>
);

const TIMEZONES = [
  { value: "America/Los_Angeles", label: "Pacific Time (US & Canada)" },
  { value: "America/Denver", label: "Mountain Time (US & Canada)" },
  { value: "America/Chicago", label: "Central Time (US & Canada)" },
  { value: "America/New_York", label: "Eastern Time (US & Canada)" },
  { value: "Europe/London", label: "Greenwich Mean Time (London)" },
  { value: "Europe/Paris", label: "Central European Time (Paris)" },
  { value: "Asia/Tokyo", label: "Japan Standard Time (Tokyo)" }
];

export default function OrganizationSettingsPage() {
  const { user, updateOrganization } = useUserContext();

  return (
    <div>
      <SettingSection title="Organization" icon={Building}>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "1rem" }}>
          {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
          <Input label="Organization Name" value={user.organization.name} onChange={(e: any) => updateOrganization({ name: e.target.value })} />
          {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
          <Input label="Website" value={user.organization.website} onChange={(e: any) => updateOrganization({ website: e.target.value })} />
          {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
          <Input label="Industry" value={user.organization.industry} onChange={(e: any) => updateOrganization({ industry: e.target.value })} />
          <Select 
            label="Timezone" 
            value={user.organization.timezone} 
            {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
            onChange={(e: any) => updateOrganization({ timezone: e.target.value })} 
            options={TIMEZONES} 
          />
          <Select 
            label="Language" 
            value={user.organization.language} 
            {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
            onChange={(e: any) => updateOrganization({ language: e.target.value })} 
            options={[
              { value: "English", label: "English" },
              { value: "Spanish", label: "Spanish" },
              { value: "French", label: "French" },
              { value: "German", label: "German" },
            ]}
          />
        </div>
      </SettingSection>

      <div style={{ display: "flex", justifyContent: "flex-end", marginTop: "1rem" }}>
        <button style={{ 
          background: T.g, border: "none", padding: "0.8rem 2rem", color: T.bg, 
          fontFamily: T.mono, fontSize: "0.8rem", fontWeight: "bold", textTransform: "uppercase",
          cursor: "pointer", boxShadow: T.glow, clipPath: "polygon(10px 0%,100% 0%,calc(100% - 10px) 100%,0% 100%)"
        }}>
          Save Organization
        </button>
      </div>
    </div>
  );
}

